import "./Users.css";

function Users({user}) {
  return (
    <div>
      {user.map((elm) => (
        <div className="userbox" key={elm.id}>
          <p className="username">{elm.login}</p>
          <p className="password">{elm.password}</p>
        </div>
      ))}
    </div>
  );
}

export default Users;
